SELECT ?ts WHERE {
  ?z a brick:Zone ; brick:hasName "Perimeter_bot_ZN_3" .
  ?p brick:isPartOf ?z ; ref:hasTimeseriesId ?ts ; ?ptype ?pt .
  FILTER (STR(?pt) = "AirTemperature")
}

